package com.bonbio.service;
import com.bonbio.dto.Dtos.*; import com.bonbio.entity.*; import com.bonbio.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.util.List;
@Service public class CommandeService { private final CommandeRepository repo; private final ClientRepository clients; private final ProduitRepository produits; public CommandeService(CommandeRepository repo,ClientRepository clients,ProduitRepository produits){this.repo=repo;this.clients=clients;this.produits=produits;} @Transactional(readOnly=true) public List<CommandeResponse> all(){return repo.findAll().stream().map(this::out).toList();} @Transactional(readOnly=true) public CommandeResponse one(Long id){return out(repo.findById(id).orElseThrow(()->new RuntimeException("Commande introuvable.")));} @Transactional public CommandeResponse save(Long id,CommandeRequest r){Commande c=id==null?new Commande():repo.findById(id).orElseThrow(()->new RuntimeException("Commande introuvable."));c.setClient(clients.findById(r.clientId()).orElseThrow(()->new RuntimeException("Client introuvable.")));c.setDateLivraison(r.dateLivraison());c.setStatut(r.statut());c.getLignes().clear();BigDecimal total=BigDecimal.ZERO;for(LigneRequest x:r.lignes()){Produit p=produits.findById(x.produitId()).orElseThrow(()->new RuntimeException("Produit introuvable."));CommandeProduit l=new CommandeProduit();l.setProduit(p);l.setQuantite(x.quantite());l.setPrixUnitaire(p.getPrix());c.addLigne(l);total=total.add(p.getPrix().multiply(BigDecimal.valueOf(x.quantite())));}c.setMontantTotal(total);return out(repo.save(c));} public void delete(Long id){repo.deleteById(id);} private CommandeResponse out(Commande c){return new CommandeResponse(c.getId(),new ClientResponse(c.getClient().getId(),c.getClient().getNom(),c.getClient().getTelephone(),c.getClient().getAdresse()),c.getDateCommande(),c.getDateLivraison(),c.getStatut(),c.getMontantTotal(),c.getLignes().stream().map(l->new LigneResponse(l.getProduit().getId(),l.getProduit().getNom(),l.getQuantite(),l.getPrixUnitaire())).toList());} }
